// Filtra e seleciona apenas leads qualificados e ainda não disparados
const items = $input.all();
const validLeads = [];

for (const item of items) {
  const lead = item.json;
  // Critérios de filtro: sem site, precisa de estoque, pendente de disparo e com whatsapp
  const isPending = lead.dispatchStatus === 'pendente' || lead.status === 'qualificado';
  const hasWhatsApp = lead.whatsapp && lead.whatsapp.length >= 10;
  const needsSite = lead.needsWebsite === true || lead.websiteStatus === 'none' || lead.websiteStatus === 'social_only';

  if (isPending && hasWhatsApp && needsSite) {
    // Formata o número para padrão DDI 55
    let cleanPhone = lead.whatsapp.replace(/\D/g, '');
    if (!cleanPhone.startsWith('55') && cleanPhone.length === 11) {
      cleanPhone = '55' + cleanPhone;
    }

    validLeads.push({
      json: {
        ...lead,
        cleanPhone,
        regionalPitch: lead.suggestedPitch || '',
        feedbackFormUrl: $env.FEEDBACK_FORM_URL || 'https://tally.so/r/app-cic-feedback',
        appDemoUrl: $env.APP_DEMO_URL || 'https://app-cic-demo.web.app'
      }
    });
  }
}

// Limita o lote de disparo diário para evitar bloqueio no WhatsApp (ex: 5 por execução)
return validLeads.slice(0, 5);

// Gera o roteiro amigável e personalizado para cada comerciante
const lead = $json;

const firstName = (lead.ownerName || 'amigo(a)').split(' ')[0];
const business = lead.businessName || 'seu comércio';
const region = lead.neighborhood ? `${lead.neighborhood} (${lead.city})` : lead.city;

// Script focado em reciprocidade e entrega do App-CIC 100% grátis sem empurrar venda
const messageText = `Olá, ${firstName}! Tudo bem?\n\nAcompanho o movimento bacana do *${business}* aqui na região de ${region}.\n\nSou desenvolvedor e desenvolvemos o *App-CIC*, um aplicativo simples de celular para controle rápido de saídas de mercadorias no balcão e avisos de falta de estoque, evitando perdas e furos no caixa.\n\nEstamos selecionando 3 comércios de destaque em ${lead.neighborhood || lead.city} para liberar o aplicativo de forma *100% gratuita*.\n\nNão cobramos nada nem pedimos cartão. O nosso único interesse é ouvir a sua opinião sincera através de um formulário rápido de feedback após o teste.\n\nPosso te mandar um vídeo de 1 minuto mostrando como funciona no celular?`;

return {
  json: {
    ...lead,
    messageText,
    targetPhone: lead.cleanPhone
  }
};

